<?php
if($page!=='employees'){require __DIR__.($page==='employee-view'?'/profile.php':'/employee-form.php');return;}
$search=substr(trim((string)($_GET['search']??'')),0,190);$department=(int)($_GET['department']??0);$role=(int)($_GET['role']??0);$status=(string)($_GET['status']??'');$incomplete=!empty($_GET['incomplete']);$p=max(1,(int)($_GET['p']??1));$where=['e.deleted_at IS NULL'];$params=[];
if($search!==''){$where[]='(u.name LIKE ? OR u.username LIKE ? OR u.email LIKE ? OR e.employee_code LIKE ?)';for($i=0;$i<4;$i++)$params[]='%'.$search.'%';}if($department){$where[]='e.department_id=?';$params[]=$department;}if($role){$where[]='ur.role_id=?';$params[]=$role;}if($status!==''){$where[]='e.employment_status=?';$params[]=$status;}if($incomplete)$where[]='(e.department_id IS NULL OR e.designation_id IS NULL OR e.joining_date IS NULL OR u.email IS NULL)';
$from=' FROM users u JOIN employees e ON e.user_id=u.id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN designations g ON g.id=e.designation_id WHERE '.implode(' AND ',$where);$q=$pdo->prepare('SELECT COUNT(*)'.$from);$q->execute($params);$count=(int)$q->fetchColumn();$pagesTotal=max(1,(int)ceil($count/20));$p=min($p,$pagesTotal);$offset=($p-1)*20;
$q=$pdo->prepare('SELECT u.id,u.name,u.email,u.username,u.active,e.employee_code,e.mobile,e.employment_status,e.joining_date,d.name department_name,g.name designation_name,r.name role_name,EXISTS(SELECT 1 FROM hr_media m WHERE m.user_id=u.id AND m.purpose=\'profile\') has_photo'.$from.' ORDER BY u.name,u.id LIMIT 20 OFFSET '.$offset);$q->execute($params);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
$departments=$pdo->query('SELECT id,name FROM departments ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$roles=$pdo->query('SELECT id,name FROM roles ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
?>
<section class="card"><form class="toolbar" method="get"><input type="hidden" name="page" value="employees"><label class="search">Search employees<input name="search" value="<?=h($search)?>" placeholder="Name, username, email or employee ID"></label><label>Department<select name="department"><option value="">All departments</option><?php foptions($departments,$department);?></select></label><label>Role<select name="role"><option value="">All roles</option><?php foptions($roles,$role);?></select></label><label>Employment status<select name="status"><option value="">All statuses</option><?php foreach(['Active','Inactive','Notice Period','Resigned','Terminated'] as $s):?><option <?=$s===$status?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><button class="button primary">Search</button><a class="button" href="?page=employees">Reset</a><?php if($incomplete):?><input type="hidden" name="incomplete" value="1"><span class="badge">Incomplete profiles</span><?php endif;?></form></section>
<section class="card table-card"><div class="table-scroll directory-table-scroll" tabindex="0" role="region" aria-label="Employee table"><table class="directory"><thead><tr><th scope="col">Employee</th><th scope="col">Employee ID</th><th scope="col">Department / designation</th><th scope="col">Role</th><th scope="col">Employment</th><th scope="col">Login</th><th scope="col">Joining date</th><th scope="col">Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="empty-state"><h2>No employees found</h2><p>Add an employee, import your workbook, or adjust your filters.</p></div></td></tr><?php endif;foreach($rows as $r):?><tr><td><a class="person" href="?page=employee-view&id=<?=$r['id']?>"><?php if($r['has_photo']):?><img class="avatar photo" src="media.php?employee=<?=$r['id']?>" alt=""><?php else:?><span class="avatar"><?=h(strtoupper(substr($r['name'],0,1)))?></span><?php endif;?><span><strong><?=h($r['name'])?></strong><small><?=h($r['email']?:$r['username'])?></small><?php if($r['mobile']):?><small><?=h($r['mobile'])?></small><?php endif;?></span></a></td><td><?=h($r['employee_code']?:'Not assigned')?></td><td><?=h($r['department_name']?:'Not assigned')?><p class="hint"><?=h($r['designation_name']?:'Not assigned')?></p></td><td><span class="badge purple"><?=h($r['role_name']?:'Employee')?></span></td><td><?php fbadge($r['employment_status'],$r['employment_status']==='Active');?></td><td><?php fbadge($r['active']?'Enabled':'Disabled',(bool)$r['active']);?></td><td><?=h($r['joining_date']?:'Not entered')?></td><td><div class="actions"><a class="button small" href="?page=employee-view&id=<?=$r['id']?>">View</a><?php if(can($pdo,$user,'employees.edit')):?><a class="button small" href="?page=employee-edit&id=<?=$r['id']?>">Edit</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><div class="pagination"><span><?=$count?> employees · Page <?=$p?> of <?=$pagesTotal?></span><div class="actions"><?php if($p>1):?><a class="button small" href="?<?=h(http_build_query(array_merge($_GET,['page'=>'employees','p'=>$p-1])))?>">Previous</a><?php endif;if($p<$pagesTotal):?><a class="button small" href="?<?=h(http_build_query(array_merge($_GET,['page'=>'employees','p'=>$p+1])))?>">Next</a><?php endif;?></div></div></section>
<?php if(can($pdo,$user,'employees.create')):?><section class="card"><details <?=isset($_SESSION['foundation_import'])?'open':''?>><summary>Import employees from Physical Id card workbook</summary><p class="hint">Uses Sheet1. Existing names are skipped. Creates first.last usernames with unique suffixes when necessary. Initial password: <strong>User@123</strong>; employees must change it at first sign-in. Employee IDs remain blank. Missing emails, departments and joining dates are not invented.</p><form method="post" enctype="multipart/form-data" class="toolbar" style="margin-top:20px"><?php ftoken();?><input type="hidden" name="action" value="preview_import"><label>Workbook (.xlsx)<input type="file" name="workbook" accept=".xlsx" required></label><button class="button">Preview import</button></form><?php if(!empty($_SESSION['foundation_import'])):$preview=$_SESSION['foundation_import'];?><h3 style="margin-top:25px"><?=count($preview)?> source employees</h3><div class="table-scroll directory-table-scroll" tabindex="0" role="region" aria-label="Employee table"><table class="directory"><thead><tr><th>Name</th><th>Designation</th><th>Suggested username</th></tr></thead><tbody><?php foreach(array_slice($preview,0,10) as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['designation'])?></td><td><?=h($r['username'])?></td></tr><?php endforeach;?></tbody></table></div><p class="hint">Showing the first <?=min(10,count($preview))?> rows. Final usernames are checked for collisions when imported.</p><form method="post" class="form-actions" data-confirm="Create accounts from this workbook? Existing names will be skipped."><?php ftoken();?><input type="hidden" name="action" value="commit_import"><button class="button primary">Import <?=count($preview)?> employees</button></form><?php endif;?></details></section><?php endif;?>
